#!/bin/bash
# Task 143-w10-chip-anomalies -- meshsim sim/ WORKER10 (branch sim-w10; kit: after 676dd66). TIMING TASK: keep the box quiet while it runs.
# The chip's placement anomalies of Quest 142 (W10): tiles at 8 threads 1.27 us against rows at 8 (the same grouping)
# 0.53, and load-1 at 6 and 8, from 7 ms runs. Measured robustly: bench_chip --reps 9 (nine machines per process after
# an untimed one), 3 processes, plain and --time, on the sort's boot. One revision (676dd66). ~3 min.
# From an embedded kit (sim/ at each revision named above). Writes only results/143-w10-chip-anomalies/. Scratch in /tmp, removed first
# and at the end. Safe to re-run.
set -u
cd "$(dirname "$0")/.."
REPO=$PWD; RES=$REPO/results/143-w10-chip-anomalies; mkdir -p "$RES"; rm -f "$RES/raw.txt"
W=/tmp/w10-143-w10-chip-anomalies; rm -rf "$W"; mkdir -p "$W"
sed -n '/^__KIT_BEGIN__$/,/^__KIT_END__$/p' "$0" | sed '1d;$d' | base64 -d > "$W/kit.tgz" || exit 2
GOT=$(sha256sum "$W/kit.tgz" | cut -d' ' -f1); echo "kit sha256 $GOT"
[ "$GOT" = "7d517cca350dcd5177470024fec76bef3642778e2cd3176d036086387a99c053" ] || { echo "kit sha256 mismatch (want 7d517cca350dcd5177470024fec76bef3642778e2cd3176d036086387a99c053)"; exit 2; }
mkdir -p "$W/kit" && tar -xzf "$W/kit.tgz" -C "$W/kit" || exit 2
KITS="after"
FAILS=0; FAIL=0
sec() { echo; echo "==== $*  [$(date +%T)]"; }
verdict() { echo "VERDICT $1: $2"; [ "$2" = PASS ] || FAIL=1; }
START=$(date +%s)
{
sec "machine (D21)"; . "$W/kit/after/sim/tools/machine.sh" "${QUEST_P_CPUS:-}" "${QUEST_E_CPUS:-}"; machine_record "$RES/machine.txt"; uptime
echo "kit: after 676dd66"
# Shared by W10's task bodies. run TAG CPUSET cmd...: one run under taskset (and perf stat when PERF=1: cycles,
# instructions, L1d load misses, LLC load misses, summed per core type); appends "TAG <bench line> [perf: ...]" to
# $RES/raw.txt. field NAME: a key=value field of stdin's lines.
run() {
  local tag=$1 cpus=$2; shift 2
  command -v perf > /dev/null || PERF=0
  if [ "${PERF:-0}" = 1 ]; then
    taskset -c "$cpus" perf stat -x, -e cycles,instructions,L1-dcache-load-misses,LLC-load-misses -o "$W/perf.csv" -- "$@" \
      > "$W/out.txt" 2> "$W/err.txt"
  else
    taskset -c "$cpus" "$@" > "$W/out.txt" 2> "$W/err.txt"
  fi
  local rc=$?
  local line; line=$(grep -E '^(threads|chip) ' "$W/out.txt" | tail -1)
  if [ $rc -ne 0 ] || [ -z "$line" ]; then echo "RUNFAIL $tag rc=$rc: $*"; head -5 "$W/err.txt"; FAILS=$((FAILS + 1)); return 1; fi
  local pc=""
  [ "${PERF:-0}" = 1 ] && pc=" perf: $(awk -F, '$1 ~ /^[0-9]+$/ { n=split($3,a,"/"); ev=(n>1)?a[2]:a[1]; k=(a[1]=="cpu_atom")?"atom":"core";
      v[k "_" ev]+=$1 } END { for (x in v) printf "%s=%s ", x, v[x] }' "$W/perf.csv")"
  echo "$tag $line$pc" | tee -a "$RES/raw.txt"
}
field() { grep -o "$1=[^ ]*" | cut -d= -f2; }
# med TAG FIELD: the median of FIELD over raw.txt's lines starting "TAG "
med() { grep "^$1 " "$RES/raw.txt" | field "$2" | sort -g | awk '{ a[NR]=$1 } END { if (NR) print a[int((NR+1)/2)]; else print "-" }'; }
# Task body (WORKER10): the chip's placement anomalies of Quest 142 (tiles at 8 threads slower than rows at 8, the same
# grouping; load-1 at 6 and 8) measured robustly: bench_chip --reps 9 (nine machines in one process after an untimed
# one), 3 processes each, plain and --time; per-machine min/median/max kept. The sort's boot.
PREPS=${PREPS:-3}; IREPS=${IREPS:-9}
sec "build (clang release, D18)"
for k in $KITS; do
  ( cd "$W/kit/$k/sim" && make -j8 CC_NAME=clang MODE=release build/clang-release/bench_chip > "$RES/build-$k.log" 2>&1 ) \
    || { tail -20 "$RES/build-$k.log"; verdict "build $k" FAIL; exit 1; }
done
NPC=$(count "$P_CPUS"); P1=$(take 1 "$P_ONE")
crun() { local tag=$1 cpus=$2 k=$3; shift 3; ( cd "$W/kit/$k/sim" && run "$tag" "$cpus" ./build/clang-release/bench_chip "$@" ); }
sec "1. one thread, then 6 and 8 threads: rows (8), tiles, load, profile; plain and timed; $PREPS processes x $IREPS machines"
for rep in $(seq $PREPS); do for k in $KITS; do
  crun "$k one" "$P1" $k --prog sort --threads 1 --cpus "$P1" --reps $IREPS
  for t in 6 8; do C=$(take $t "$PLACE")
    for p in rows tiles load profile; do
      [ "$p" = rows ] && [ "$t" != 8 ] && continue
      crun "$k t$t-$p" "$P_CPUS" $k --prog sort --threads $t --partition $p --cpus "$C" --reps $IREPS
      crun "$k t$t-$p-timed" "$P_CPUS" $k --prog sort --threads $t --partition $p --cpus "$C" --reps $IREPS --time
    done
  done
done; done
sec "2. digests"
n=$(grep "chip prog=sort" "$RES/raw.txt" | field digest | sort -u | wc -l); [ "$n" = 1 ] && verdict "digests" PASS || verdict "digests: $n distinct" FAIL
sec "3. summary: per configuration, every process's median/min/max (us per cycle) and the timed run's shares x its median"
for k in $KITS; do for tag in one t6-tiles t6-load t6-profile t8-rows t8-tiles t8-load t8-profile; do
  echo "$k $tag: $(grep "^$k $tag " "$RES/raw.txt" | awk '{ for (i = 1; i <= NF; i++) if ($i ~ /^us_(per_cycle|min|max)=/) printf "%s ", $i; printf "| " }')"
  grep "^$k $tag-timed " "$RES/raw.txt" | while read -r l; do
    u=$(echo "$l" | field us_per_cycle); s="  timed us=$u"
    for f in compute imbalance barrier_wait drain publish clear; do v=$(echo "$l" | field $f | tr -d '"'); s+=" $f=$(awk -v a=$v -v u=$u 'BEGIN { printf "%.3f", a * u }')"; done
    echo "$s"
  done
done; done | tee "$RES/summary.txt"
[ "$FAILS" = 0 ] && verdict "every run completed" PASS || verdict "every run completed ($FAILS failed)" FAIL
sec "done in $(($(date +%s) - START)) s"
} 2>&1 | tee "$RES/run.log"
grep '^VERDICT' "$RES/run.log" > "$RES/VERDICTS.txt"
rm -rf "$W"
grep -q ': FAIL$' "$RES/VERDICTS.txt" && exit 1
exit 0
